fn matching_request_bindings<'a>(
    lockfile: &'a Lockfile,
    short: &str,
    specifier: &str,
    mut matches_options: impl FnMut(&LockfileTool) -> Result<bool>,
) -> (Vec<&'a LockfileTool>, Option<Report>) {
